/* ============================================================
 * app.js —— A-SOUL Games Optimization (AsoulOpt) 控制面板
 *
 * 控制原理（与模块 customize.sh 完全一致）：
 *   配置文件 /data/adb/naki/asopt.conf
 *     全局行：mode=<0|1|2>   rt=<0|1>
 *     分游戏行：<包名> <mode> <rt>
 *   保存后调用模块自带 service.sh 重启 AsoulOpt，使配置即时生效。
 *   （作者说明：保存后即时应用，切换游戏后生效）
 * ============================================================ */

const APP = (function () {
    'use strict';

    const P = {
        conf: '/data/adb/naki/asopt.conf',
        confDir: '/data/adb/naki',
        moddir: '/data/adb/modules/asoul_affinity_opt',
        binary: '/data/adb/modules/asoul_affinity_opt/AsoulOpt',
        service: '/data/adb/modules/asoul_affinity_opt/service.sh'
    };

    const MODES = [
        { id: '0', name: '硬亲和', desc: '把线程固定在指定核心，理论上表现更好' },
        { id: '1', name: '软迁移', desc: '允许调度器迁移，帧率可能更稳定' },
        { id: '2', name: '硬迁移', desc: '强制迁移策略，帧率可能更稳定' }
    ];

    const RTS = [
        { id: '0', name: '默认', desc: '保持调度器默认行为' },
        { id: '1', name: '实时', desc: '可能更流畅，也可能导致卡死' }
    ];

    let gMode = '0';
    let gRt = '0';
    let games = [];        // [{ pkg, mode, rt }]
    let busy = false;

    /* ---------------- 读取封装 ----------------
     * 读取路径一律不抛异常：桥接不可用或某条命令超时只让对应字段为空，
     * 不让整个 load() 中断，避免页面停在半渲染状态。
     */

    function safeExec(cmd, opts, timeout) {
        return KSU.exec(cmd, opts, timeout).catch(function (e) {
            return { errno: -1, stdout: '', stderr: (e && e.message) ? e.message : String(e) };
        });
    }

    function safeRead(path) {
        return safeExec('cat ' + Util.q(path) + ' 2>/dev/null').then(function (r) {
            return r.stdout || '';
        });
    }

    /* ---------------- 解析 / 序列化 ---------------- */

    const HEADER = [
        '# A-SOUL Games Optimization 配置',
        '# 由 WebUI 生成 / generated by module WebUI',
        '#',
        '# mode：运行模式 / Operation Mode',
        '#   0：硬亲和，理论上表现更好 / Affinity, performs better in theory',
        '#   1：软迁移，帧率可能更稳定 / Soft migrate, fps maybe more stable',
        '#   2：硬迁移，帧率可能更稳定 / Hard migrate, fps maybe more stable',
        '#',
        '# rt：实时模式 / Real-Time Mode',
        '#   0：调度器默认行为 / Scheduler default behavior',
        '#   1：可能更流畅，但可能导致卡死 / maybe smoother, but may cause freeze',
        '#',
        '# 分游戏覆盖格式 / per-game format：<包名> <mode> <rt>',
        '# 例 / e.g.: com.miHoYo.Yuanshen 0 0',
        '# 未匹配的游戏使用全局值 / unmatched games use the global values above',
        '# ***保存后即时应用，切换游戏后生效***',
        ''
    ].join('\n');

    function parseConf(text) {
        const res = { mode: '0', rt: '0', games: [] };
        String(text || '').split('\n').forEach(function (raw) {
            const line = raw.replace(/\r$/, '').trim();
            if (!line || line.charAt(0) === '#') return;

            let m = line.match(/^mode\s*=\s*([0-9]+)/);
            if (m) { res.mode = m[1]; return; }

            m = line.match(/^rt\s*=\s*([0-9]+)/);
            if (m) { res.rt = m[1]; return; }

            // <pkg> <mode> <rt>
            m = line.match(/^([^\s]+)\s+([0-9]+)\s+([0-9]+)$/);
            if (m) {
                res.games.push({ pkg: m[1], mode: m[2], rt: m[3] });
            }
        });
        return res;
    }

    function serializeConf() {
        let s = HEADER;
        s += 'mode=' + gMode + '\n';
        s += 'rt=' + gRt + '\n';
        games.forEach(function (g) {
            s += g.pkg + ' ' + g.mode + ' ' + g.rt + '\n';
        });
        return s;
    }

    /* ---------------- 加载 ---------------- */

    async function load() {
        const text = await safeRead(P.conf);
        const parsed = parseConf(text);

        // 配置文件缺失时，用模块默认值兜底（与 customize.sh 的默认一致）
        gMode = parsed.mode;
        gRt = parsed.rt;
        games = parsed.games;

        renderModes();
        renderRts();
        renderGames();

        const confExists = !!text.trim();
        Util.el('confPath').textContent = P.conf;
        Util.el('confState').className = 'pill ' + (confExists ? 'ok' : 'warn');
        Util.el('confState').textContent = confExists ? '已加载' : '未找到，使用默认值';
        Util.el('gameCount').textContent = games.length + ' 个';

        await refreshStatus();
    }

    async function refreshStatus() {
        const r = await safeExec('pidof AsoulOpt 2>/dev/null || pgrep -f "[A]soulOpt" 2>/dev/null');
        const pid = (r.stdout || '').trim();
        const pill = Util.el('daemonPill');
        if (pid) {
            pill.className = 'pill ok';
            pill.innerHTML = '<span class="dot"></span>运行中 · PID ' + Util.escapeHtml(pid.split(/\s+/)[0]);
        } else {
            pill.className = 'pill danger';
            pill.innerHTML = '<span class="dot"></span>未运行';
        }
    }

    /* ---------------- 渲染 ---------------- */

    function chipRow(host, items, current, onPick) {
        host.innerHTML = '';
        items.forEach(function (it) {
            const b = Util.make('button', 'mode' + (it.id === current ? ' on' : ''));
            b.type = 'button';
            b.appendChild(Util.make('div', 'mode-name', it.name));
            b.appendChild(Util.make('div', 'mode-desc', it.desc));
            b.addEventListener('click', function () { onPick(it.id); });
            host.appendChild(b);
        });
    }

    function renderModes() {
        chipRow(Util.el('modeGrid'), MODES, gMode, function (id) {
            gMode = id;
            renderModes();
            saveConf('运行模式已设为「' + modeName(id) + '」');
        });
        Util.el('modeNow').textContent = modeName(gMode);
    }

    function renderRts() {
        chipRow(Util.el('rtGrid'), RTS, gRt, function (id) {
            gRt = id;
            renderRts();
            saveConf('实时模式已设为「' + rtName(id) + '」');
        });
        Util.el('rtNow').textContent = rtName(gRt);
    }

    function modeName(id) {
        const m = MODES.filter(function (x) { return x.id === id; })[0];
        return m ? m.name : id;
    }
    function rtName(id) {
        const m = RTS.filter(function (x) { return x.id === id; })[0];
        return m ? m.name : id;
    }

    function renderGames() {
        const box = Util.el('gameList');
        box.innerHTML = '';

        if (!games.length) {
            box.appendChild(Util.make('div', 'empty',
                '暂无分游戏规则，所有游戏使用全局的「' + modeName(gMode) + ' / ' + rtName(gRt) + '」'));
            return;
        }

        games.forEach(function (g, idx) {
            const row = Util.make('div', 'rule stack');

            const main = Util.make('div', 'rule-main');
            const ico = Util.make('div', 'rule-ico');
            const img = document.createElement('img');
            img.src = Util.iconUrl(g.pkg, true);
            img.alt = '';
            img.addEventListener('error', function () {
                ico.textContent = Util.initialOf(g.pkg);
            });
            ico.appendChild(img);
            main.appendChild(ico);

            const body = Util.make('div', 'rule-body');
            body.appendChild(Util.make('div', 'rule-name', g.label || g.pkg));
            body.appendChild(Util.make('div', 'rule-pkg', g.pkg));
            main.appendChild(body);
            row.appendChild(main);

            const controls = Util.make('div', 'rule-controls');

            const selM = document.createElement('select');
            selM.className = 'mode-sel';
            selM.style.maxWidth = '110px';
            MODES.forEach(function (m) {
                const o = document.createElement('option');
                o.value = m.id;
                o.textContent = m.name;
                if (m.id === g.mode) o.selected = true;
                selM.appendChild(o);
            });
            selM.addEventListener('change', function () {
                games[idx].mode = selM.value;
                saveConf('已更新 ' + g.pkg);
            });
            controls.appendChild(selM);

            const selR = document.createElement('select');
            selR.className = 'mode-sel';
            selR.style.maxWidth = '92px';
            RTS.forEach(function (m) {
                const o = document.createElement('option');
                o.value = m.id;
                o.textContent = 'rt ' + m.name;
                if (m.id === g.rt) o.selected = true;
                selR.appendChild(o);
            });
            selR.addEventListener('change', function () {
                games[idx].rt = selR.value;
                saveConf('已更新 ' + g.pkg);
            });
            controls.appendChild(selR);

            const del = Util.make('button', 'rule-del', '✕');
            del.type = 'button';
            del.title = '删除该游戏规则';
            del.addEventListener('click', function () {
                games.splice(idx, 1);
                renderGames();
                saveConf('已删除 ' + g.pkg);
            });
            controls.appendChild(del);

            row.appendChild(controls);
            box.appendChild(row);
        });
    }

    /* ---------------- 保存 ---------------- */

    async function saveConf(okMsg) {
        try {
            const ok = await Util.writeText(P.conf, serializeConf());
            if (!ok) { Util.tip('写入失败：' + P.conf + ' 不可写'); return; }
            await restartService(false);
            Util.tip(okMsg || '已保存');
            Util.el('gameCount').textContent = games.length + ' 个';
        } catch (e) {
            Util.tip('保存失败：' + describeError(e));
        }
    }

    /* ---------------- 重启服务 ---------------- */

    async function restartService(notify) {
        const has = await Util.exists(P.service);
        if (!has) {
            Util.tip('未找到 ' + P.service);
            return;
        }
        await safeExec('timeout 25 sh ' + Util.q(P.service) + ' >/dev/null 2>&1', {}, 40000);
        await new Promise(function (r) { setTimeout(r, 1200); });
        await refreshStatus();
        if (notify) Util.tip('已重启 AsoulOpt');
    }

    /* ---------------- 添加游戏 ---------------- */

    async function openPicker() {
        let list;
        try {
            list = await Util.packages(false);
        } catch (e) {
            list = [];
        }
        if (!list.length) { Util.tip('无法获取应用列表'); return; }

        let sh = null;
        sh = UI.sheet({
            title: '选择游戏',
            search: true,
            placeholder: '搜索游戏名或包名…',
            render: function (host) {
                const render = function (kw) {
                    host.innerHTML = '';
                    const used = Object.create(null);
                    games.forEach(function (g) { used[g.pkg] = 1; });

                    const filtered = list.filter(function (p) {
                        if (used[p.packageName]) return false;
                        if (!kw) return true;
                        const k = kw.toLowerCase();
                        return p.packageName.toLowerCase().indexOf(k) >= 0
                            || String(p.label).toLowerCase().indexOf(k) >= 0;
                    }).slice(0, 300);

                    if (!filtered.length) {
                        host.appendChild(Util.make('div', 'empty', '没有匹配的应用'));
                        return;
                    }

                    const wrap = Util.make('div', 'pkg-list');
                    filtered.forEach(function (p) {
                        const row = Util.make('div', 'pkg');
                        const ico = Util.make('div', 'rule-ico');
                        const img = document.createElement('img');
                        img.src = Util.iconUrl(p.packageName, p.hasIcon);
                        img.alt = '';
                        img.addEventListener('error', function () {
                            ico.textContent = Util.initialOf(p.label);
                        });
                        ico.appendChild(img);
                        row.appendChild(ico);

                        const body = Util.make('div', 'rule-body');
                        body.appendChild(Util.make('div', 'rule-name', p.label));
                        body.appendChild(Util.make('div', 'rule-pkg', p.packageName));
                        row.appendChild(body);

                        row.addEventListener('click', function () {
                            games.push({ pkg: p.packageName, mode: gMode, rt: gRt, label: p.label });
                            renderGames();
                            saveConf('已添加「' + p.label + '」');
                            sh.destroy();
                        });
                        wrap.appendChild(row);
                    });
                    host.appendChild(wrap);

                    const manual = Util.make('div', 'pkg-add', '手动输入包名…');
                    manual.addEventListener('click', function () {
                        const pn = window.prompt('请输入包名，例如 com.miHoYo.Yuanshen');
                        if (!pn) return;
                        const v = pn.trim();
                        if (!v) return;
                        games.push({ pkg: v, mode: gMode, rt: gRt });
                        renderGames();
                        saveConf('已添加 ' + v);
                        sh.destroy();
                    });
                    host.appendChild(manual);
                };
                sh.onSearch = render;
                render('');
            }
        });
    }

    /* ---------------- 重置 ---------------- */

    function resetDefaults() {
        gMode = '0';
        gRt = '0';
        games = [];
        renderModes();
        renderRts();
        renderGames();
        saveConf('已恢复默认配置');
    }

    /* ---------------- 错误 ---------------- */

    function describeError(e) {
        const msg = (e && e.message) ? e.message : String(e);
        if (msg === 'NO_BRIDGE') return '当前 root 管理器未提供 WebUI 接口';
        if (msg === 'TIMEOUT') return '命令超时';
        return msg;
    }

    /* ---------------- 启动 ---------------- */

    async function init() {
        Theme.init();

        Util.el('btnTheme').addEventListener('click', function () { Theme.cycle(); });
        Util.el('btnRefresh').addEventListener('click', async function () {
            await load();
            Util.tip('已刷新');
        });
        Util.el('btnAdd').addEventListener('click', openPicker);
        Util.el('btnRestart').addEventListener('click', function () { restartService(true); });
        Util.el('btnReset').addEventListener('click', function () {
            if (window.confirm('确定恢复默认配置？将清空全部分游戏规则。')) resetDefaults();
        });

        if (!KSU.available()) {
            Util.el('envBanner').appendChild(UI.banner('danger',
                '<b>未检测到 WebUI 桥接接口。</b>本页面需要支持 webroot 的 root 管理器'
                + '（KernelSU / KernelSU-Next / APatch，或配合 MMRL 使用），'
                + '且需以 WebUI 方式打开，而非普通浏览器。'));
            Util.el('envBanner').classList.remove('hidden');
        } else {
            const installed = await Util.isDir(P.moddir);
            if (!installed) {
                Util.el('envBanner').appendChild(UI.banner('warn',
                    '<b>未在 ' + Util.escapeHtml(P.moddir) + ' 找到模块目录。</b>'
                    + '请确认 A-SOUL Games Optimization 已安装并重启过设备。'));
                Util.el('envBanner').classList.remove('hidden');
            } else {
                const binOk = await Util.exists(P.binary);
                if (!binOk) {
                    Util.el('envBanner').appendChild(UI.banner('warn',
                        '<b>未找到可执行文件 ' + Util.escapeHtml(P.binary) + '。</b>'
                        + '配置仍可保存，但需要重启设备后由 service.sh 拉起。'));
                    Util.el('envBanner').classList.remove('hidden');
                }
            }
        }

        const info = KSU.moduleInfo();
        if (info) {
            if (info.name) Util.el('modName').textContent = info.name;
            if (info.version) Util.el('modVersion').textContent = 'v' + info.version;
        }

        // 先渲染静态骨架，再读配置：桥接不可用时页面结构依然完整
        renderModes();
        renderRts();
        renderGames();

        await load();
    }

    return { init: init };
})();

document.addEventListener('DOMContentLoaded', function () {
    APP.init().catch(function (e) {
        console.error(e);
        try { Util.tip('初始化失败：' + (e && e.message ? e.message : e)); } catch (x) { /* ignore */ }
    });
});
